"""Maintain the grandfathered baseline for the ratcheted Ruff rules.

The rules in ``RATCHETED_RULES`` enforce the exception-handling policy in
``docs/source/guides/python-code-style.md``. Existing violations are recorded in
``ruff-baseline.toml`` so the rules apply to all new code immediately while the
old code is cleaned up file by file.

The baseline stores the exact violation count for each file and rule, and
``--check`` fails when the recorded and actual counts differ in either
direction. A fix therefore has to delete or lower its baseline entry, and a new
violation inside an already-grandfathered file cannot hide behind the file-level
ignore. ``--write`` regenerates the file; review its diff like any other change.

Usage::

    uv run --script .github/scripts/ruff_baseline.py            # check, print coverage
    uv run --script .github/scripts/ruff_baseline.py --write    # regenerate the baseline
"""

from __future__ import annotations

import argparse
import json
import os
import re
import shutil
import subprocess
import sys
import tomllib
from collections import Counter, defaultdict
from collections.abc import Mapping, Sequence
from pathlib import Path

# The rules governed by the baseline. Keep in step with `select` in ruff.toml.
RATCHETED_RULES = ("BLE001", "S110", "S112", "B904")

# Must equal the version pinned in .github/workflows/lint.yml and
# .pre-commit-config.yaml so the baseline is generated by the linter CI runs.
RUFF_VERSION = "0.15.16"

BASELINE_NAME = "ruff-baseline.toml"
_ROOT = Path(__file__).resolve().parents[2]

# Directories whose first two path components name the owning project.
_NESTED_AREAS = {"agent-sdk", "agent-samples", "services", "utils"}

_HEADER = f"""\
# SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
# SPDX-License-Identifier: Apache-2.0

# GENERATED by .github/scripts/ruff_baseline.py --write. Do not edit by hand.
#
# Grandfathered violations of the ratcheted Ruff rules ({", ".join(RATCHETED_RULES)}).
# New code must pass these rules cleanly. Each comment records the exact
# violation count per rule; the check fails if the file drifts from the code, so
# an entry can only be removed or lowered as violations are fixed. Regenerate
# with `uv run --script .github/scripts/ruff_baseline.py --write`.

[lint.extend-per-file-ignores]
"""

_ENTRY = re.compile(r'^"(?P<path>[^"]+)"\s*=\s*\[[^\]]*\]\s*#\s*(?P<counts>.+)$')
Counts = dict[tuple[str, str], int]


def _ruff_command() -> list[str]:
    """Return a command that runs the pinned Ruff, or exit with instructions."""
    ruff = shutil.which("ruff")
    if ruff is not None:
        version = subprocess.run([ruff, "--version"], capture_output=True, text=True, check=True).stdout
        if version.split()[-1] == RUFF_VERSION:
            return [ruff]
    uv = shutil.which("uv")
    if uv is not None:
        return [uv, "tool", "run", f"ruff@{RUFF_VERSION}"]
    sys.exit(f"ruff {RUFF_VERSION} is required: install it or install uv")


def _excludes(root: Path) -> list[str]:
    """Return the `extend-exclude` globs from ruff.toml."""
    config = tomllib.loads((root / "ruff.toml").read_text(encoding="utf-8"))
    return list(config.get("extend-exclude", []))


def scan(root: Path) -> Counts:
    """Count current violations per (file, rule), ignoring the baseline itself.

    ``--isolated`` skips ruff.toml, and with it the baseline's ignores; the
    repository's exclusions are passed back in explicitly. Inline ``# noqa``
    comments still apply, which is how a deliberate exception is recorded.
    """
    command = [
        *_ruff_command(),
        "check",
        "--isolated",
        "--no-cache",
        "--output-format=json",
        "--select",
        ",".join(RATCHETED_RULES),
    ]
    for pattern in _excludes(root):
        command += ["--extend-exclude", pattern]
    # Ruff exits 1 when it reports violations; only >1 is a failure to run.
    result = subprocess.run([*command, "."], cwd=root, capture_output=True, text=True)
    if result.returncode > 1:
        sys.exit(f"ruff failed:\n{result.stderr}")
    counts: Counter[tuple[str, str]] = Counter()
    for violation in json.loads(result.stdout):
        relative = Path(violation["filename"]).resolve().relative_to(root).as_posix()
        counts[(relative, violation["code"])] += 1
    return dict(counts)


def linted_files(root: Path) -> list[str]:
    """List the Python files Ruff lints under the repository configuration."""
    result = subprocess.run(
        [*_ruff_command(), "check", "--show-files", "."], cwd=root, capture_output=True, text=True, check=True
    )
    return sorted(
        Path(line).resolve().relative_to(root).as_posix() for line in result.stdout.splitlines() if line.strip()
    )


def render(counts: Mapping[tuple[str, str], int]) -> str:
    """Render the baseline file for ``counts``."""
    by_file: dict[str, dict[str, int]] = defaultdict(dict)
    for (path, rule), count in counts.items():
        by_file[path][rule] = count
    lines = []
    for path in sorted(by_file):
        rules = sorted(by_file[path])
        quoted = ", ".join(f'"{rule}"' for rule in rules)
        summary = " ".join(f"{rule}={by_file[path][rule]}" for rule in rules)
        lines.append(f'"{path}" = [{quoted}]  # {summary}')
    return _HEADER + "\n".join(lines) + ("\n" if lines else "")


def parse(text: str) -> Counts:
    """Read the per-file counts back out of a rendered baseline."""
    counts: Counts = {}
    for line in text.splitlines():
        match = _ENTRY.match(line)
        if match is None:
            continue
        for item in match["counts"].split():
            rule, _, count = item.partition("=")
            counts[(match["path"], rule)] = int(count)
    return counts


def compare(actual: Mapping[tuple[str, str], int], recorded: Mapping[tuple[str, str], int]) -> list[str]:
    """Describe every difference between the code and the baseline."""
    problems = []
    for key in sorted(set(actual) | set(recorded)):
        path, rule = key
        now, then = actual.get(key, 0), recorded.get(key, 0)
        if now > then:
            problems.append(f"{path}: {rule} has {now} violation(s), baseline allows {then}: fix the new code")
        elif now < then:
            problems.append(f"{path}: {rule} has {now} violation(s), baseline records {then}: run --write")
    return problems


def _area(path: str) -> str:
    parts = path.split("/")
    return "/".join(parts[:2]) if parts[0] in _NESTED_AREAS and len(parts) > 2 else parts[0]


def summary(files: Sequence[str], counts: Mapping[tuple[str, str], int], excluded: Sequence[str]) -> str:
    """Render the enforcement coverage report in Markdown."""
    total = len(files)
    lines = [f"### Ratcheted Ruff rules: {total} Python files linted", ""]
    lines += ["| Rule | Files clean | Files grandfathered | Violations left |", "|---|---|---|---|"]
    for rule in RATCHETED_RULES:
        flagged = {path for (path, r) in counts if r == rule}
        violations = sum(n for (_, r), n in counts.items() if r == rule)
        clean = total - len(flagged)
        lines.append(f"| {rule} | {clean} ({clean / total:.0%}) | {len(flagged)} | {violations} |")
    area_files = Counter(_area(path) for path in files)
    area_flagged: dict[str, set[str]] = defaultdict(set)
    area_violations: Counter[str] = Counter()
    for (path, _), count in counts.items():
        area_flagged[_area(path)].add(path)
        area_violations[_area(path)] += count
    lines += ["", "| Area | Files | Grandfathered files | Violations |", "|---|---|---|---|"]
    for area in sorted(area_files, key=lambda a: (-area_violations[a], a)):
        lines.append(f"| {area} | {area_files[area]} | {len(area_flagged[area])} | {area_violations[area]} |")
    lines += ["", f"Not linted at all (`extend-exclude`): {', '.join(f'`{p}`' for p in excluded)}"]
    return "\n".join(lines)


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--write", action="store_true", help="regenerate ruff-baseline.toml")
    args = parser.parse_args(argv)

    baseline = _ROOT / BASELINE_NAME
    actual = scan(_ROOT)
    if args.write:
        baseline.write_text(render(actual), encoding="utf-8")
        print(f"wrote {BASELINE_NAME}: {sum(actual.values())} violation(s) in {len({p for p, _ in actual})} file(s)")
        return 0

    recorded = parse(baseline.read_text(encoding="utf-8")) if baseline.exists() else {}
    report = summary(linted_files(_ROOT), actual, _excludes(_ROOT))
    print(report)
    step_summary = os.environ.get("GITHUB_STEP_SUMMARY")
    if step_summary:
        with open(step_summary, "a", encoding="utf-8") as handle:
            handle.write(report + "\n")
    problems = compare(actual, recorded)
    if problems:
        print("\n" + "\n".join(problems), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
